@if(isset($methods['card']))
<script src="https://js.stripe.com/v3/"></script><script>
document.addEventListener('DOMContentLoaded',()=>{
 const stripe=window.Stripe(@json($methods['card']['public_key'])); const card=stripe.elements().create('card'); let mounted=false;
 const area=document.getElementById('cardArea'); const form=document.getElementById('paymentForm');
 const change=()=>{const selected=form.querySelector('input[name="payment_method"]:checked')?.value;area.classList.toggle('active',selected==='card');if(selected==='card'&&!mounted){card.mount('#card-element');mounted=true;}};
 form.querySelectorAll('input[name="payment_method"]').forEach(input=>input.addEventListener('change',change));change();
 form.addEventListener('submit',async event=>{if(form.querySelector('input[name="payment_method"]:checked')?.value!=='card')return;event.preventDefault();
 const button=document.getElementById('paymentSubmit');const errorBox=document.getElementById('paymentError');button.disabled=true;errorBox.hidden=true;
 try{const data=new FormData(form);const response=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:data});const payload=await response.json();if(!response.ok)throw new Error(payload.message||payload.error||'Card payment could not begin.');const result=await stripe.confirmCardPayment(payload.client_secret,{payment_method:{card}});if(result.error)throw new Error(result.error.message);window.location.href=@json(url('/payments'))+'/'+payload.payment_id;}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;button.disabled=false;}
 });
});
</script>
