<script>document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('service_id'),amount=document.getElementById('amount');if(!select)return;const sync=()=>{const price=select.selectedOptions[0]?.dataset.price;if(price){amount.value=price;amount.readOnly=true}else amount.readOnly=false};select.addEventListener('change',sync);sync();});</script>
